sys_variable_value.value:
(function execute(inputs, outputs) {
    var result = false;
    var gr_import_set = new GlideRecord(fd_data.action_inputs.import_job_table);
    if(!gr_import_set.get(fd_data.action_inputs.import_job_sys_id)) {
        throw "Scheduled job not found!";
    }
    gr_import_set.update();
    outputs.result = gr_import_set.setValue("run_start", fd_data.action_inputs.run_start);
})(inputs, outputs);

